import{_ as s,C as o,o as r,c as i,j as t,a,E as h,ah as c}from"./chunks/framework.Dmqp7bmQ.js";const k=JSON.parse('{"title":"Deployment","description":"","frontmatter":{},"headers":[],"relativePath":"deployment.md","filePath":"deployment.md"}'),l={name:"deployment.md"};function d(p,e,u,m,f,g){const n=o("Mermaid");return r(),i("div",null,[e[0]||(e[0]=t("h1",{id:"deployment",tabindex:"-1"},[a("Deployment "),t("a",{class:"header-anchor",href:"#deployment","aria-label":'Permalink to "Deployment"'},"​")],-1)),e[1]||(e[1]=t("p",null,[a("WRX1 runs on an internal or air-gapped network with nothing fetched from the internet. One server holds everything: the XMPP server, the client the browsers load, and the game's data. The full operator's guide is in the repository ("),t("code",null,"ops/README.md"),a("); this page is the outline.")],-1)),h(n,{code:"flowchart%20LR%0A%20%20%20%20subgraph%20Connected%5B%22Connected%20machine%22%5D%0A%20%20%20%20%20%20%20%20Repo%5B%22Repository%22%5D%20--%3E%20Bundle%5B%22make-bundle.sh%22%5D%0A%20%20%20%20end%0A%20%20%20%20Bundle%20--%3E%7C%22one%20file%20%2B%20its%20SHA-256%22%7C%20Install%0A%20%20%20%20subgraph%20Host%5B%22WRX1%20host%2C%20no%20network%20needed%22%5D%0A%20%20%20%20%20%20%20%20Install%5B%22offline-install.sh%22%5D%20--%3E%20Server%5B%22ejabberd%20container%3A%20the%20client%20and%20XMPP%20over%20a%20secure%20WebSocket%2C%20on%20one%20HTTPS%20address%22%5D%0A%20%20%20%20%20%20%20%20Server%20--%3E%20Data%5B(%22Accounts%2C%20rooms%2C%20archives%2C%20documents%22)%5D%0A%20%20%20%20%20%20%20%20Backup%5B%22backup.sh%20%2F%20restore.sh%22%5D%20---%20Data%0A%20%20%20%20end%0A%20%20%20%20Browsers%5B%22Analysts'%20browsers%2C%20trusting%20the%20internal%20CA%22%5D%20--%3E%7C%22HTTPS%20and%20WebSocket%20over%20TLS%22%7C%20Server%0A"}),e[2]||(e[2]=c('<h2 id="one-container-one-origin" tabindex="-1">One container, one origin <a class="header-anchor" href="#one-container-one-origin" aria-label="Permalink to &quot;One container, one origin&quot;">​</a></h2><p>The reference deployment is a single container: the official ejabberd 26.09 image, pinned to an exact image digest, with the project&#39;s reference configuration. It serves the built client and its WebSocket from the same HTTPS origin, so the browser needs no other address, and it sends the client&#39;s Content-Security-Policy as a header. Only one port is published, and it speaks TLS 1.2 or later.</p><p>The same configuration file runs in CI, where every transport contract test, admin scenario and deployment check passes against it before a change is merged.</p><h2 id="offline-install" tabindex="-1">Offline install <a class="header-anchor" href="#offline-install" aria-label="Permalink to &quot;Offline install&quot;">​</a></h2><p>On a machine with network access, <code>make-bundle.sh</code> packs the image, the built client, the configuration and the scripts into one file, with a checksum for every file inside it. On the target host, <code>offline-install.sh</code> checks the bundle, loads the image and checks it is the pinned one, installs the files, starts the server, creates the admin account (asking for its password, which is never written down) and runs a set of checks from the outside. Running it again with a newer bundle is an upgrade: it backs up first and keeps all data.</p><p>The install is tested here inside a container with networking switched off, and the whole contract suite then runs against that installation. A container is not a host, so the first deployment is also checked on the real hardware by a person, with a checklist in the guide.</p><h2 id="certificates-from-an-internal-ca" tabindex="-1">Certificates from an internal CA <a class="header-anchor" href="#certificates-from-an-internal-ca" aria-label="Permalink to &quot;Certificates from an internal CA&quot;">​</a></h2><p>Browsers must trust the server&#39;s certificate. The scripts support both cases:</p><ul><li><strong>The organisation has a CA:</strong> a script makes the server&#39;s key and a signing request for it.</li><li><strong>It has none:</strong> a script makes a small CA that can only vouch for the exercise&#39;s own domain, and signs the server&#39;s certificate with it.</li></ul><p>The guide shows how to make Windows, macOS, Linux and Firefox trust the CA, by group policy or by hand.</p><h2 id="backup-and-restore" tabindex="-1">Backup and restore <a class="header-anchor" href="#backup-and-restore" aria-label="Permalink to &quot;Backup and restore&quot;">​</a></h2><p><code>backup.sh</code> takes a consistent copy while the server runs: accounts, rooms with their settings and message archives, the game&#39;s documents and theme images, and the admin&#39;s stored data. <code>restore.sh</code> puts it back, on the same host or a new one. The test behind it publishes a game, backs up, deletes the whole installation, installs again, restores, and checks that every account, room, message, document and setting is back.</p><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><p>Which browsers analysts use, who approves running the server software on internal hosts, who checks the install on the real hardware, and how the customer distributes CA certificates are still to be answered. Each answer changes configuration, not code.</p>',14))])}const w=s(l,[["render",d]]);export{k as __pageData,w as default};
